/**
 * Heroes and heroines: the people whose lives, cases or campaigns changed cancer. Patients whose cases became
 * turning points, families who built funds, advocates who changed the rules, and pioneers who refused the odds.
 *
 * Rules for this file:
 *  - Every record carries the tag "hero" plus at least one of "patient", "advocate", "pioneer", "carer".
 *  - Public record only: dates, published accounts, foundation and obituary pages. No medical detail beyond it.
 *  - People who already have a record elsewhere in the corpus (Carl June, James Allison, Dennis Slamon,
 *    Steven Rosenberg) are linked from here via `people`, not duplicated.
 *  - Living people are included only where they have a public profile and made their story public themselves.
 *  - Corrections and additions via the GitHub issue template linked from /heroes/.
 */
const asOf = "2026-09-09";
type P = Omit<PersonInput, "kind" | "asOf">;
const p = (x: P): PersonInput => ({ kind: "person", asOf, links: x.profiles, ...x });
const W = (slug: string) => `https://en.wikipedia.org/wiki/${slug}`;
const wiki = (slug: string) => ({ label: "Wikipedia", url: W(slug) });
const site = (label: string, url: string) => ({ label, url });

